head.script:
scwin.screenId = "jldbnf05007";

///////// 1. 변수 및 선언 영역 /////////

scwin.comboDiv = $c.util.getComponent('comboDiv');

scwin.textDiv = $c.util.getComponent('textDiv');

scwin.rownum = 1;

scwin.frn_bas_int_tp_cd2 = "";

scwin.frn_bas_int_tp_cd3 = "";

scwin.frn_bas_int_tp_cd4 = "";

scwin.frn_bas_int_misc = "";

scwin.frn_isur_cd = "";

scwin.frn_isur_nm = "";

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.rownum = undefined;


///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "cal_intPayDd1", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("intPayDd1")))); } },
        { childId: "cal_intRtChgDd1", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("intRtChgDd1")))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_datefmt_cal_intRtDecsnBasDd
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_datefmt_cal_intRtDecsnBasDd = function () { $c.date.checkCalendarFormat("cal_intRtDecsnBasDd", "yyyyMMdd"); };

/**
 * @method
 * @name scwin.init_datefmt_cal_intPayDd1
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_datefmt_cal_intPayDd1 = function () { $c.date.checkCalendarFormat("cal_intPayDd1", "yyyyMMdd"); };

/**
 * @method
 * @name scwin.init_datefmt_cal_intRtChgDd1
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_datefmt_cal_intRtChgDd1 = function () { $c.date.checkCalendarFormat("cal_intRtChgDd1", "yyyyMMdd"); };

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.makeInputFromParent();
        $('#ipt_frnIsurCd').on('keypress', function(e) {
                if (e.which == 13) {
                    window_iss_inst_cd('frn_isur_cd', 'frn_isur_nm');
                }
        });
        await scwin.setFrnCombo($c.util.getComponent('slc_frnBasIntTpCd1').getValue());
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf05007.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_datefmt_cal_intRtDecsnBasDd();
        scwin.init_datefmt_cal_intPayDd1();
        scwin.init_datefmt_cal_intRtChgDd1();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldbnf05007.onpageload' });
    }
};


