/**
 * @method
 * @name scwin.toggleObjectStat
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj isActive
 * @returns
 * @hidden N
*/
scwin.toggleObjectStat = function (obj, isActive) {
    /* sdd-asis-lifecycle:begin fn_ToggleObjectStat — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!obj) {
        return;
    }
    if (isActive) {
        obj.style.backgroundColor = "";
        obj.disabled = false;
        if (obj.tagName === "SELECT") {
            obj.selectedIndex = 0;
        }
    } else {
        obj.style.background = '#e2e2e2';
        obj.disabled = true;
        if (obj.tagName === "SELECT") {
            obj.selectedIndex = -1;
        } else {
            obj.value = "";
        }
    }
    /* sdd-asis-lifecycle:end */
};


