/**
 * @method
 * @name scwin.autoCalcDone
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.autoCalcDone = async function (data) {
    /* sdd-asis-lifecycle:begin fn_autoCalc_done — as-is 원문 본문(전환 이관 · 포팅 적용됨) */result = (typeof data === "string" ? JSON.parse(data) : data);
    let alertYn = "N";
    $(result.arrList).each(function(i, item) {
            if (i == 0) {
                $c.util.getComponent('cal_intPayDd1').setValue(item.day);
                $c.util.getComponent('cal_intRtChgDd1').setValue(item.bday);
            } else {
                scwin.addRow();
                $("input[name='int_pay_dd_" + (i + 1) + "']").val(item.day);
                $("input[name='int_rt_chg_dd_" + (i + 1) + "']").val(item.bday);
            }
            if (item.alert === 'Y') {
                alertYn = 'Y';
            } else {
                alertYn = 'N';
            }
    });
    if (alertYn === 'Y') {
        await $c.win.alert("'이자지급일'에 유효하지 않은 일자가 포함되어있습니다. \n\r'최초 이자지급일' 또는 '이자월말구분'을 확인하여 주시기 바랍니다.");
    }
    /* sdd-asis-lifecycle:end */
};

