    $(result.arrList).each(function(i, item) {
            if (item.cd_eng_nm === "FRN_BAS_INT_TP_CD2") {
                $c.util.getComponent('slc_comboFrnBasIntTpCd2').addItem(item.cd, item.cd_nm);
